using Microsoft.AspNetCore.Mvc;using Microsoft.EntityFrameworkCore;using RentalCamera.Data;using RentalCamera.ViewModels;
namespace RentalCamera.Controllers; public class BaoCaoController:BaseController{private readonly RentalCameraDbContext _db;public BaoCaoController(RentalCameraDbContext db)=>_db=db;public async Task<IActionResult> Index(string ky="thang"){var paid=_db.ThanhToan.Where(x=>x.TrangThai=="THANH_CONG"&&new[]{"TIEN_THUE","PHI_GIA_HAN","PHI_PHAT"}.Contains(x.LoaiThanhToan));var total=await paid.SumAsync(x=>(decimal?)x.SoTien)??0;var count=await _db.HopDong.CountAsync(x=>x.TrangThai!="DA_HUY");var dev=await _db.ThietBi.CountAsync();var rent=await _db.ThietBi.CountAsync(x=>x.TrangThai=="DANG_THUE"||x.TrangThai=="DANG_GIU");var now=DateTime.Today;
 DateTime currentStart=ky=="tuan"?now.AddDays(-((int)now.DayOfWeek+6)%7):new DateTime(now.Year,now.Month,1);
 DateTime previousStart=ky=="tuan"?currentStart.AddDays(-7):currentStart.AddMonths(-1);
 DateTime currentEnd=ky=="tuan"?currentStart.AddDays(7):currentStart.AddMonths(1);
 var comparison=await paid.AsNoTracking().Where(x=>x.ThoiGian>=previousStart&&x.ThoiGian<currentEnd).GroupBy(x=>x.ThoiGian>=currentStart).Select(g=>new{IsCurrent=g.Key,Revenue=g.Sum(x=>x.SoTien)}).ToListAsync();
 ViewBag.Ky=ky=="tuan"?"tuan":"thang";ViewBag.DoanhThuHienTai=comparison.Where(x=>x.IsCurrent).Sum(x=>x.Revenue);ViewBag.DoanhThuTruoc=comparison.Where(x=>!x.IsCurrent).Sum(x=>x.Revenue);ViewBag.KyHienTai=$"{currentStart:dd/MM/yyyy} - {currentEnd.AddDays(-1):dd/MM/yyyy}";ViewBag.KyTruoc=$"{previousStart:dd/MM/yyyy} - {currentStart.AddDays(-1):dd/MM/yyyy}";
 return View(new ReportVM{DoanhThu=total,DonThanhCong=count,TongThietBi=dev,TyLeLapDay=dev==0?0:(decimal)rent/dev*100,DoanhThuTheoLoai=await paid.GroupBy(x=>x.LoaiThanhToan).ToDictionaryAsync(g=>g.Key,g=>g.Sum(x=>x.SoTien)),TinhTrangThietBi=await _db.ThietBi.GroupBy(x=>x.TrangThai).ToDictionaryAsync(g=>g.Key,g=>g.Count()),DonTheoTrangThai=await _db.HopDong.GroupBy(x=>x.TrangThai).ToDictionaryAsync(g=>g.Key,g=>g.Count())});}}
